    outside = set()
    stack = []
    for r, c in ((0, 0), (0, w - 1), (h - 1, 0), (h - 1, w - 1)):
        if grid[r][c] == bg and (r, c) not in outside:
            outside.add((r, c))
            stack.append((r, c))

    while stack:
        r, c = stack.pop()
        for nr, nc in ((r - 1, c), (r + 1, c), (r, c - 1), (r, c + 1)):
            if (0 <= nr < h and 0 <= nc < w and grid[nr][nc] == bg
                    and (nr, nc) not in outside):
                outside.add((nr, nc))
                stack.append((nr, nc))

    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if grid[r][c] == bg and (r, c) not in outside:
                out[r][c] = 4
    return out
